def build_agent(sandbox):
    # Construct a compact, buoyant structure with optimized beam dimensions and density
    beam_w = 0.5  # width
    beam_h = 0.5  # height
    density = 10.0  # lower density for better buoyancy
    centers_x = [2.31 + i * 0.62 for i in range(9)]
    y_center = 0.5 + beam_h / 2
    bodies = []
    for x in centers_x:
        b = sandbox.add_beam(x, y_center, beam_w, beam_h, angle=0, density=density)
        sandbox.set_material_properties(b, restitution=0.05)
        bodies.append(b)
    for i in range(8):
        anchor_x = (centers_x[i] + centers_x[i + 1]) / 2
        sandbox.add_joint(bodies[i], bodies[i + 1], (anchor_x, y_center), type='rigid')
    return bodies[-1]

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return
    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0
    if front_x >= target_x + 0.1:
        # Stop all movement
        for b in sandbox.bodies:
            if b.active:
                b.linearVelocity = (0, 0)
                b.angularVelocity = 0
        return

    # Thrust cooldown tracking (simplified as step_count modulo 200)
    if step_count % 200 == 0:
        # Apply thrust to the front body for forward motion
        front_body = sandbox.bodies[-1]
        fx = 520.0  # Max thrust force
        fy = 0.0

        # Check if in deep channel (reduced buoyancy zone)
        in_danger_zone = (12.0 <= front_x <= 22.0)
        if in_danger_zone:
            fy = 400.0  # Lift force to counteract reduced buoyancy

        # Apply force to the front body
        sandbox.apply_force(front_body, fx, fy, step_count=step_count)

    # Adjust velocity based on current speed to prevent over-thrusting
    for b in sandbox.bodies:
        if not b.active:
            continue
        vx = b.linearVelocity.x
        if vx > 1.8:
            # Reduce thrust if moving too fast
            for b in sandbox.bodies:
                if b.active:
                    b.linearVelocity = (vx * 0.1, b.linearVelocity.y)
        elif vx > 1.0:
            # Slightly reduce thrust if moving at moderate speed
            for b in sandbox.bodies:
                if b.active:
                    b.linearVelocity = (vx * 0.4, b.linearVelocity.y)
